import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { testD1 } from "../../test/d1.js";
import type { QueueRouteEnv } from "./routes.js";
import { loadQueueState } from "./queue-state.js";
import { runOnQueue } from "./routes.js";
import type { D1Like } from "./projection.js";

vi.mock("./BranchQueue.js", () => ({ BranchQueue: class {} }));
vi.mock("../github-app.js", async (original) => ({
  ...(await original<Record<string, unknown>>()),
  installationToken: async () => "installation-token",
}));
const { queueFromPullRequest } = await import("../index.js");
const { authorizeTurn } = await import("./authorize-turn.js");

const open: Array<{ close(): void }> = [];
let raw: import("better-sqlite3").Database;

const REPO = "1315419165";
const REF = "refs/heads/main";
const HEAD = "5".repeat(40);
const ENTRY = `entry_${REPO}_120`;
const FAR = "2099-01-01T00:00:00Z";
const digest = (ch: string) => `sha256:${ch.repeat(64)}`;

function env(): QueueRouteEnv {
  const t = testD1();
  open.push(t);
  raw = t.raw;
  raw
    .prepare("INSERT INTO organizations (id, github_org_id, github_login, installation_id) VALUES (?, ?, ?, ?)")
    .run("org_1", "1", "acme", "9001");
  raw
    .prepare(
      "INSERT INTO queue_projects (id, organization_id, github_repository_id, base_ref, enabled, activation_state) VALUES (?, ?, ?, ?, 1, 'enforced')",
    )
    .run("qp_1", "org_1", REPO, REF);
  raw
    .prepare(
      "INSERT INTO projects (id, organization_id, github_repository_id, github_name, enabled) VALUES (?, ?, ?, ?, 1)",
    )
    .run("proj_1", "org_1", REPO, "acme/repo");
  raw
    .prepare(
      "INSERT INTO principals (id, organization_id, github_user_id, github_login, activated_at) VALUES (?, ?, ?, ?, datetime('now'))",
    )
    .run("alice", "org_1", "1", "alice");
  return { DB: t.db, PUBLIC_ORIGIN: "https://thwip.test" } as unknown as QueueRouteEnv;
}

beforeEach(() => {
  vi.stubGlobal(
    "fetch",
    vi.fn(async (input: string | URL | Request) =>
      String(input).includes("/check-runs") ? Response.json({ check_runs: [] }) : Response.json([]),
    ),
  );
});

afterEach(() => {
  vi.unstubAllGlobals();
  while (open.length > 0) open.pop()!.close();
});

function draftPayload(action = "converted_to_draft") {
  return {
    action,
    pull_request: {
      number: 120,
      draft: true,
      state: "open",
      base: { ref: "main", repo: { id: Number(REPO) } },
      head: { sha: HEAD },
      user: { id: 1, login: "alice", type: "User" },
    },
  };
}

type Ev = Record<string, unknown>;
async function appendAll(e: QueueRouteEnv, events: Ev[]) {
  const loaded = await loadQueueState(e.DB as unknown as D1Like, REPO, REF);
  for (const [i, ev] of events.entries()) {
    const result = loaded.store.append({
      idempotencyKey: `probe:${i}:${String(ev.type)}`,
      at: new Date().toISOString(),
      ...ev,
    } as never);
    if (result.status === "rejected") throw new Error(`append ${String(ev.type)} rejected: ${result.detail}`);
  }
  await loaded.save();
}

const requested: Ev = {
  type: "QueueRequested",
  entryId: ENTRY,
  pullRequestNumber: 120,
  sponsorPrincipalId: "alice",
  sponsorGithubUserId: "1",
  headSha: HEAD,
};
const ready: Ev = {
  type: "ReadinessEvaluated",
  entryId: ENTRY,
  ready: true,
  schedulerEligible: true,
  primaryReason: null,
  secondaryReasons: [],
};
const offered: Ev = {
  type: "TurnOffered",
  entryId: ENTRY,
  attemptId: "att_probe",
  offerDeadline: FAR,
  decisionDigest: digest("a"),
};
const runningPrefix: Ev[] = [
  { type: "OfferClaimed", attemptId: "att_probe", executionMode: "device", deviceId: "dev_1" },
  {
    type: "CandidatePrepared",
    attemptId: "att_probe",
    baseSha: "4".repeat(40),
    headSha: HEAD,
    candidateSha: "6".repeat(40),
    candidateTree: "7".repeat(40),
    policyDigest: digest("b"),
    runner: "device",
  },
  { type: "AssignmentIssued", attemptId: "att_probe", assignmentDigest: digest("c"), executionDeadline: FAR },
  { type: "HeartbeatReceived", attemptId: "att_probe" },
];

async function stateOf(e: QueueRouteEnv) {
  const { store } = await loadQueueState(e.DB as unknown as D1Like, REPO, REF);
  const s = store.state();
  return {
    entry: s.entries.get(ENTRY),
    attempt: s.attempts.get("att_probe"),
    activeAttemptId: s.activeAttemptId,
  };
}

describe("PR #316 probe", () => {
  it("draft during ReconnectGrace", async () => {
    const e = env();
    await appendAll(e, [requested, ready, offered, ...runningPrefix, { type: "HeartbeatLost", attemptId: "att_probe", graceUntil: FAR }]);
    expect((await stateOf(e)).entry?.state).toBe("ReconnectGrace");

    const result = await queueFromPullRequest(e as never, draftPayload());
    const after = await stateOf(e);
    console.log("RESULT detail:", result.detail);
    console.log("entry:", after.entry?.state, "attempt outcome:", after.attempt?.outcome, "activeAttemptId:", after.activeAttemptId);
  });

  it("draft during Reconciling", async () => {
    const e = env();
    await appendAll(e, [
      requested,
      ready,
      offered,
      ...runningPrefix,
      { type: "ReceiptSubmitted", attemptId: "att_probe", receiptDigest: digest("d") },
      { type: "VerificationStarted", attemptId: "att_probe", nonce: "n1" },
      { type: "VerificationCompleted", attemptId: "att_probe", nonce: "n1", accepted: true, resultDigest: digest("e") },
      { type: "MergeIntentCreated", attemptId: "att_probe", intentDigest: digest("f") },
      { type: "MergeRequested", attemptId: "att_probe" },
      { type: "MergeOutcomeUnknown", attemptId: "att_probe" },
    ]);
    expect((await stateOf(e)).entry?.state).toBe("Reconciling");

    const result = await queueFromPullRequest(e as never, draftPayload());
    const after = await stateOf(e);
    console.log("RESULT detail:", result.detail);
    console.log("entry:", after.entry?.state, "attempt outcome:", after.attempt?.outcome, "outcomeUnknown:", after.attempt?.outcomeUnknown);
  });

  it("draft during MergeGuard (HOLDING) is left alone", async () => {
    const e = env();
    await appendAll(e, [
      requested,
      ready,
      offered,
      ...runningPrefix,
      { type: "ReceiptSubmitted", attemptId: "att_probe", receiptDigest: digest("d") },
      { type: "VerificationStarted", attemptId: "att_probe", nonce: "n1" },
      { type: "VerificationCompleted", attemptId: "att_probe", nonce: "n1", accepted: true, resultDigest: digest("e") },
    ]);
    expect((await stateOf(e)).entry?.state).toBe("MergeGuard");
    const result = await queueFromPullRequest(e as never, draftPayload());
    const after = await stateOf(e);
    console.log("RESULT detail:", result.detail, "entry:", after.entry?.state);
  });

  it("the /authorize poll re-admits a withdrawn draft", async () => {
    const e = env();
    await appendAll(e, [requested, { ...ready, ready: false, schedulerEligible: true, primaryReason: "LOCAL_RECEIPT_MISSING" }]);
    const withdrawn = await queueFromPullRequest(e as never, draftPayload());
    expect(withdrawn.handled).toBe(true);
    expect((await stateOf(e)).entry?.state).toBe("Cancelled");

    const onQueue = ((env: QueueRouteEnv, repositoryId: string, baseRef: string, decide: never) =>
      runOnQueue(env, repositoryId, baseRef, decide)) as never;
    const deps = {
      queueProject: async () => ({ activationState: "enforced" }),
      principalFor: async () => "alice",
      pullRequestPlacement: async () => ({
        authorGithubUserId: "1",
        baseRef: REF,
        authorIsBot: false,
        draft: true,
        headSha: HEAD,
      }),
      activePolicy: async () => null,
      commitFacts: async () => ({ treeOid: "t".repeat(40), parentShas: [] }),
      proofCheckRunId: async () => null,
      signRecordBytes: async () => "jws",
    };
    const answer = await authorizeTurn(e as never, deps as never, onQueue, {
      repositoryId: REPO,
      baseRef: REF,
      pullRequestNumber: 120,
      headSha: HEAD,
      authorGithubUserId: "1",
      draft: true,
    });
    const after = await stateOf(e);
    console.log("authorize outcome:", answer.outcome, "reason" in answer ? answer.reason : "");
    console.log("entry after /authorize poll:", after.entry?.state, "reason:", after.entry?.primaryReason);
  });
});

